//! Tool configuration and reusable modules share the native wire format.
use crate::{model::{Model,Action,Dialog,DialogKind,Field},widgets::Ui,draw::{self,Icon,rect}};
use serde_json::{Value,json};
impl Model{
 pub fn edit_timer_preferences(&mut self){self.dialog=Some(Dialog{kind:DialogKind::TimerPreferences,fields:vec![Field::new(if self.mode==0{"专注时长 · 秒"}else{"倒计时时长 · 秒"},self.timer_seconds.unwrap_or(self.minutes*60).to_string(),6),Field::new("番茄钟休息时长 · 秒",self.rest_seconds.to_string(),4),Field::new("番茄钟轮数 · 1–16",self.timer_rounds.to_string(),2)],active:0,daily:self.setting("FocusCountUp")==true,error:String::new(),preedit:String::new()});}
 pub fn save_timer_preferences(&mut self,d:&Dialog)->Result<(),String>{let parse=|i:usize|d.fields[i].value.trim().parse::<u32>().map_err(|_|"请填写整数".to_string());let seconds=parse(0)?;let rest=parse(1)?;let rounds=parse(2)?;if seconds==0||seconds>if self.mode==0{14400}else{86400}{return Err("计时时长超出范围：番茄钟最多 4 小时，倒计时最多 24 小时。".into())}if !(1..=3600).contains(&rest)||!(1..=16).contains(&rounds){return Err("休息时长需要 1–3600 秒，轮数需要 1–16。".into())}self.timer_seconds=Some(seconds);self.minutes=seconds.div_ceil(60);self.rest_seconds=rest;self.timer_rounds=rounds;self.selected=None;self.native_state["settings"]["FocusCountUp"]=json!(d.daily);self.native_update("FocusCountUp",json!(d.daily));Ok(())}
 pub fn edit_module(&mut self,index:Option<usize>){let modules=crate::workflow::modules(self);let module=index.and_then(|i|modules.get(i));self.dialog=Some(Dialog{kind:DialogKind::WorkflowModule(index),fields:vec![Field::new("模块名称",module.map(|m|m.name.clone()).unwrap_or_default(),40),Field::new("时长 · 分钟",module.map(|m|m.minutes).unwrap_or(10).to_string(),3)],active:0,daily:false,error:String::new(),preedit:String::new()});}
 pub fn store_modules(&mut self,list:Vec<Value>){let value=json!(list);self.native_state["settings"]["WorkflowModules"]=value.clone();self.native_update("WorkflowModules",value);}
 pub fn save_module(&mut self,d:&Dialog,index:Option<usize>)->Result<(),String>{let name=d.fields[0].value.trim();let minutes=d.fields[1].value.trim().parse::<u32>().map_err(|_|"时长需要填写整数分钟".to_string())?;if name.is_empty()||!(1..=240).contains(&minutes){return Err("请填写模块名称和 1–240 分钟的时长".into())}let mut modules=crate::workflow::modules(self).iter().map(|m|json!({"id":m.id,"name":m.name,"minutes":m.minutes,"kind":m.kind})).collect::<Vec<_>>();if let Some(i)=index{let m=modules.get_mut(i).ok_or("模块不存在")?;m["name"]=json!(name);m["minutes"]=json!(minutes);}else{if modules.len()>=24{return Err("模块库最多保存 24 个模块".into())}let id=format!("user-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos());modules.push(json!({"id":id,"name":name,"minutes":minutes,"kind":5}));}self.store_modules(modules);Ok(())}
 pub fn remove_module(&mut self,index:usize){let mut modules=crate::workflow::modules(self).iter().map(|m|json!({"id":m.id,"name":m.name,"minutes":m.minutes,"kind":m.kind})).collect::<Vec<_>>();if index<modules.len(){modules.remove(index);self.store_modules(modules);}}
}
pub fn modules_dialog(ui:&mut Ui,m:&Model,width:f64,height:f64){let s=ui.s;let modules=crate::workflow::modules(m);let pages=modules.len().div_ceil(8).max(1);let page=m.module_page.min(pages-1);let w=640.;let h=480.;let x=(width-w)/2.;let y=(height-h)/2.;ui.panel(rect(x,y,w,h),s.surface);ui.label("流程模块库",x+28.,y+24.,26.,s.on_surface,true,280.);ui.button(rect(x+w-248.,y+24.,152.,40.),"新建模块",Some(Icon::Plus),Action::EditModule(None),false,modules.len()<24);ui.icon_button(rect(x+w-72.,y+20.,44.,44.),Icon::Close,"关闭模块库",Action::CancelModal,false,true);ui.label("编辑或删除不会改动已经创建的流程。",x+28.,y+74.,13.,s.on_surface_variant,false,w-56.);
 let cw=(w-64.)/2.;for(index,module)in modules.iter().enumerate().skip(page*8).take(8){let cell=index-page*8;let cx=x+28.+(cell%2)as f64*(cw+8.);let cy=y+112.+(cell/2)as f64*64.;let r=rect(cx,cy,cw,56.);draw::fill(ui.scene,r,16.,s.high);ui.label(&module.name,cx+14.,cy+7.,15.,s.on_surface,true,cw-106.);ui.label(&format!("{} 分钟",module.minutes),cx+14.,cy+31.,11.,s.on_surface_variant,false,cw-106.);ui.icon_button(rect(cx+cw-86.,cy+8.,36.,40.),Icon::Settings,"编辑模块",Action::EditModule(Some(index)),false,true);ui.icon_button(rect(cx+cw-46.,cy+8.,36.,40.),Icon::Trash,"删除模块",Action::RemoveModule(index),false,true);}
 if modules.is_empty(){ui.center("模块库为空，可以新建一个模块。",rect(x+28.,y+178.,w-56.,44.),16.,s.on_surface_variant,false);}
 ui.button(rect(x+28.,y+h-68.,100.,40.),"上一页",None,Action::ModulePage(page.saturating_sub(1)),true,page>0);ui.center(&format!("{} / {}",page+1,pages),rect(x+140.,y+h-68.,88.,40.),13.,s.on_surface_variant,false);ui.button(rect(x+240.,y+h-68.,100.,40.),"下一页",None,Action::ModulePage(page+1),true,page+1<pages);ui.button(rect(x+w-140.,y+h-68.,112.,40.),"完成",None,Action::CancelModal,true,true);
}
